    massacre: ["Masacre", "El primero en matar 5 unidades rivales (cualesquiera) gana."],
    chasse: ["Caza del dios", "El primero en matar un dios rival gana."],
    percee: ["Brecha", "El primero en llevar un guardia o un soldado a la zona de despliegue rival gana."],
