Object.assign(I18N.DICT.es.T, {"rq": ["Tiburón", "Nada en línea recta (arriba, abajo, izquierda, derecha) hasta 3 casillas; captura al llegar sobre un enemigo."], "mz": ["Medusa", "Da 1 paso en diagonal, o pica sin moverse a un enemigo pegado a ella en línea recta (arriba, abajo, izquierda, derecha)."], "pv": ["Pulpo", "Sus tentáculos atrapan a un enemigo a 2 o 3 casillas (en las 8 direcciones, por encima de todo) y lo traen pegado a él. Ni dioses ni jefes."], "sr": ["Sirena", "Su canto empuja una casilla a todos los enemigos pegados a ella; los empujados fuera del mapa o a un agujero mueren."], "bl": ["Leviatán", "Jefe, 4 puntos de vida. Un turno de cada dos, se sumerge (no se le puede tocar) y marca en rojo la casilla de tu guardia o soldado más valioso; al turno siguiente, surge debajo y lo devora."], "bm": ["Señor de las mareas", "Jefe, 4 puntos de vida. Un turno de cada dos, la marea empuja a todas tus unidades una casilla hacia tu campo."], "bo": ["Gran Coral", "Jefe, 5 puntos de vida. Al final de cada turno de su bando, crece coral (una casilla bloqueada) pegado a él o a su coral, hacia ti (6 como máximo). Cada 3 turnos recupera 1 punto de vida."], "bj": ["Medusa gigante", "Jefe, 3 puntos de vida. Un turno de cada dos, un rayo golpea a tu unidad más cercana a ella (a 3 casillas o menos) y luego salta a una de tus unidades pegada a esa."], "bx": ["Dios caído", "Jefe final, en 2 fases. Primero (3 puntos de vida) llama a un secuaz cada turno y aplasta a una unidad pegada a él un turno de cada dos. Luego se levanta (4 puntos de vida): avanza hacia ti y escupe fuego en línea un turno de cada dos."], "om": ["Madre de las sombras", "Hace salir una Sombra (un soldado de las sombras de la reserva común) en una casilla vacía pegada a una de tus unidades."], "of": ["Segador", "Mata a un enemigo (no un dios) pegado a una de tus unidades."], "oe": ["Eclipse", "Sume el mapa en la oscuridad: en su próximo turno, el rival no puede ni colocar ni activar unidades."], "ou": ["Devorador de almas", "Sacrifica a una de tus unidades pegadas a él (no un dios): ganas 50 de maná."], "oa": ["Asesino", "Da 1 paso a una casilla vacía, o salta 2 casillas (en línea recta o en diagonal, por encima de todo); captura al llegar sobre un enemigo."], "ob": ["Bruma", "Se teletransporta a una casilla vacía a 3 casillas o menos, o sobre un enemigo a 2 casillas o menos para capturarlo."], "oc": ["Cuervo", "Vuela en diagonal hasta 3 casillas por encima de todo; captura al llegar sobre un enemigo."], "ol": ["Hoja", "Avanza 2 casillas en línea recta (arriba, abajo, izquierda, derecha) y mata a los enemigos que atraviesa."], "ox": ["Murciélago", "Vuela 2 casillas (en línea recta o en diagonal) por encima de todo; captura al llegar sobre un enemigo."], "os": ["Sombra", "Soldado de las sombras: da 1 paso recto (incluso hacia atrás) a una casilla vacía; captura en diagonal hacia delante."], "bv": ["Corazón de lava", "Jefe, 4 puntos de vida. Un turno de cada dos, marca en rojo la casilla de tu guardia o soldado más valioso; al turno siguiente, la lava brota allí: si sigue encima, muere."]});
I18N.DICT.es.SPEC[3] = ["Corriente", "Al final de tu turno, cada una de tus unidades sobre una corriente es arrastrada una casilla en el sentido de la flecha (si la casilla está libre)."];
