I18N.DICT.es.T.mz[1] = "Da 1 paso en cualquier dirección, o pica sin moverse a un enemigo pegado a ella (en las 8 direcciones).";
I18N.DICT.es.T.rq[1] = "Nada en línea recta (arriba, abajo, izquierda, derecha) hasta 4 casillas; captura al llegar sobre un enemigo.";
I18N.DICT.es.THEME.nuit = ["Bosque de noche"];
I18N.DICT.es.T.c5[1] = "Se posa en cualquier casilla a más de 5 casillas (filas + columnas); puede capturar allí un soldado, o un guardia a más de 6 casillas, nunca un dios.";
I18N.DICT.es.T.mz[1] = "Da 1 paso en cualquier dirección a una casilla vacía, o pica sin moverse a todos los enemigos pegados a ella en línea recta (arriba, abajo, izquierda, derecha).";
I18N.DICT.es.T.g4[1] = "Avanza 1 casilla en las 8 direcciones empujando toda la fila de delante (una unidad empujada fuera del mapa o a un agujero muere), y luego puede dar un 2.º paso a una casilla vacía o sobre un enemigo para capturarlo.";
I18N.DICT.es.T.mz[1] = "Da 1 paso en cualquier dirección a una casilla vacía, o pica sin moverse a un enemigo a 1 o 2 casillas en línea recta (arriba, abajo, izquierda, derecha), incluso por encima de una unidad.";
I18N.DICT.es.T.c5[1] = "Se posa en cualquier casilla a más de 5 casillas (filas + columnas); puede capturar allí un soldado, o un guardia a más de 7 casillas, nunca un dios.";
I18N.DICT.es.T.g4[1] = "Avanza 1 casilla en las 8 direcciones empujando toda la fila de delante (una unidad empujada fuera del mapa o a un agujero muere), y luego puede dar un 2.º paso a una casilla vacía o sobre un enemigo (no un dios) para capturarlo.";
I18N.DICT.es.T.g1[1] = "Intercambia su sitio con cualquier unidad del mapa (aliada o rival, incluso un dios). Si elige a un enemigo pegado a él, lo captura en lugar de intercambiarse.";
// DLC « Les Ombres » : boss de la Lumière et nouvelles cases
Object.assign(I18N.DICT.es.T, {"sa": ["Arcángel", "Jefe de la Luz, 4 puntos de vida. Cada dos turnos, su luz ciega a todas tus unidades de su fila y su columna: no puedes activarlas en tu siguiente turno."], "sp": ["Paladín", "Jefe de la Luz, 3 puntos de vida. Mientras 2 de sus unidades estén pegadas a él, lo protegen: tus golpes no le hacen nada. ¡Mata primero a sus guardias! Avanza hacia ti cada dos turnos (a veces dejando atrás a sus guardias) y golpea a una unidad pegada a él cada 4 turnos."], "sl": ["Faro", "Jefe de la Luz, 2 puntos de vida. No se mueve, pero su luz paraliza a tus guardias y soldados: los que están a 2 casillas o menos no se pueden activar (tus dioses sí). ¡Golpéalo de lejos! Cada 4 turnos llama a un esbirro."], "sg": ["Gólem de cristal", "Jefe de la Luz, 2 puntos de vida. Su cristal devuelve los disparos y los hechizos: solo le hieren los golpes cuerpo a cuerpo. Cada 4 turnos aplasta a una unidad pegada a él."]});
I18N.DICT.es.SPEC[4] = ["Altar de las sombras", "Al empezar tu turno, si una de tus unidades de las Sombras está encima: +20 de maná."];
I18N.DICT.es.SPEC[5] = ["Luz sagrada", "Una unidad de las Sombras (no un dios) que siga encima al final del turno de su bando muere."];
I18N.DICT.es.SPEC[6] = ["Portal", "Al final de tu turno, tu unidad sobre un portal pasa por el portal gemelo (al otro lado del mapa), si está libre."];
// armée des Ombres complète : noms des jumeaux
Object.assign(I18N.DICT.es.T, {"na": ["Tormenta negra"], "nb": ["Espejo oscuro"], "nc": ["Manipulador"], "nd": ["Jefe de la manada"], "ne": ["Ojeador"], "nf": ["Reloj de arena negro"], "ng": ["Sima"], "nh": ["Cuerno de las sombras", "Una de tus Sombras (soldado de las sombras) da 2 pasos seguidos."], "ni": ["Invocador", "Recluta una Sombra (soldado de las sombras) y la coloca directamente en tu zona de despliegue."], "nj": ["Cadenas"], "nk": ["Venganza"], "n1": ["Doble"], "n2": ["Torre negra"], "n3": ["Arquera oscura"], "n4": ["Mastodonte"], "n5": ["Merodeador"], "n6": ["Tormento"], "n7": ["Fuego fatuo"], "n8": ["Gárgola"], "n9": ["Sacerdote oscuro"], "nl": ["Ballesta de hueso"], "nm": ["Catapulta de hueso"], "nn": ["Jinete sin cabeza"], "no": ["Centinela"]});
// armée des Ombres : pouvoirs à elle
Object.assign(I18N.DICT.es.T, {"na": ["Posesión", "Toma el control de un soldado o guardia enemigo pegado a una de tus unidades: pasa a tu bando (cuenta como perdido para el rival)."], "nb": ["Maldición", "Maldice a un enemigo (no un dios) en cualquier lugar del mapa: si sigue en la misma casilla al final del próximo turno de su bando, muere."], "nc": ["Pasaje", "Hace pasar una de tus unidades (no un dios) por las sombras: sale en una casilla vacía pegada a otra de tus unidades."], "nd": ["Ladrón de almas", "Roba hasta 30 de maná al rival."], "ne": ["Aullido", "Todos los enemigos (no los dioses) que están en tu mitad del mapa retroceden una casilla hacia su lado, si la casilla está libre."], "nf": ["Llamada de los muertos", "Hace entrar 2 Sombras (soldados de las sombras) en tu reserva, más 1 por cada guardia que hayas perdido (4 como máximo)."], "ng": ["Grillete", "Encadena a una unidad enemiga (incluso un dios): no puede activarse durante los 2 próximos turnos de su bando."], "nh": ["Puerta de las sombras", "Abre una puerta: uno de tus guardias o soldados sale en una casilla vacía de la zona de despliegue rival."], "ni": ["Plaga", "Mueren todos los soldados enemigos pegados al menos a 2 de tus unidades."], "nj": ["Sudario", "Cubre a una de tus unidades y a tus unidades pegadas a ella: nada puede matarlas hasta tu próximo turno."], "nk": ["Marea negra", "Todas tus Sombras (soldados de las sombras) avanzan una casilla hacia el rival, si la casilla está libre."], "n1": ["Fantasma", "Lo atraviesa todo: se posa en una casilla vacía a 3 casillas o menos. Donde llega, los soldados enemigos pegados mueren de miedo y los guardias enemigos pegados no pueden activarse en su próximo turno."], "n2": ["Necrófago", "Da 1 paso en cualquier dirección; captura al llegar sobre un enemigo. Tras una captura, puede dar otro paso (3 pasos como máximo)."], "n3": ["Vampiro", "Da 1 paso a una casilla vacía (8 direcciones), o muerde sin moverse a un enemigo a 1 o 2 casillas en línea recta o en diagonal, por encima de todo (no un dios): el enemigo muere y ganas 20 de maná."], "n4": ["Araña", "Da 1 paso recto a una casilla vacía, o lanza su tela sobre la 1.ª unidad enemiga en línea recta a 4 casillas o menos: un soldado muere, un guardia o un dios no puede activarse durante 2 turnos de su bando."], "n5": ["Poltergeist", "Da 1 paso recto a una casilla vacía, o agarra a un enemigo a 1 o 2 casillas en línea recta o en diagonal (no un dios) y lo lanza 2 casillas más lejos: si cae fuera del mapa, en un agujero o sobre una unidad, muere."], "n6": ["Serpiente", "Repta hasta 3 pasos rectos (arriba, abajo, izquierda, derecha), girando como quiera, por casillas vacías; captura al llegar sobre un enemigo."], "n7": ["Hombre lobo", "Da 1 paso en cualquier dirección (captura al llegar sobre un enemigo). Si está pegado a 2 enemigos o más, puede entrar en furia: mueren todos los enemigos pegados a él (no los dioses)."], "n8": ["Larva", "Da 1 paso recto a una casilla vacía, o captura en diagonal. Cuando muere, nacen 2 Sombras a su alrededor."], "n9": ["Demonio", "Da 1 paso en cualquier dirección (captura al llegar sobre un enemigo), o surge en una casilla vacía pegada a un dios enemigo."], "nl": ["Esqueleto", "Da 1 paso recto (captura al llegar sobre un enemigo), o lanza un hueso sin moverse a un enemigo a 2 o 3 casillas en línea recta (no un dios). Cuando muere, se levanta como Sombra justo al lado."], "nm": ["Reflejo", "Da 1 paso recto a una casilla vacía, o salta a su reflejo: la casilla simétrica en la misma fila, al otro lado (izquierda ↔ derecha); allí captura a un enemigo, no a un dios."], "nn": ["Verdugo", "Da 1 paso a una casilla vacía (8 direcciones), o ejecuta sin moverse a un enemigo pegado a él (no un dios) que también esté pegado a otra de tus unidades."], "no": ["Reptante", "Repta en línea recta hacia el rival, hasta 4 casillas, por casillas vacías; captura al llegar sobre un enemigo."]});
I18N.DICT.es.T.oa[1] = "Da 1 paso a una casilla vacía, o salta a 2 o 3 casillas (en línea recta o en diagonal, por encima de todo); captura al llegar sobre un enemigo.";
I18N.DICT.es.T.oc[1] = "Vuela en diagonal hasta 4 casillas por encima de todo; captura al llegar sobre un enemigo.";
// armée des Ombres : descriptions courtes
I18N.DICT.es.T.na[1] = "Roba un enemigo (no un dios) pegado a una de tus unidades: se une a tu bando.";
I18N.DICT.es.T.nb[1] = "Maldice a un enemigo: si no se mueve en su turno, muere.";
I18N.DICT.es.T.nc[1] = "Teletransporta una de tus unidades junto a otra.";
I18N.DICT.es.T.nd[1] = "Roba 40 de maná al rival.";
I18N.DICT.es.T.ne[1] = "Hace retroceder una casilla a todos los enemigos de tu mitad del mapa.";
I18N.DICT.es.T.nf[1] = "+3 Sombras (soldados) en tu reserva, +1 por guardia perdido.";
I18N.DICT.es.T.ng[1] = "Un enemigo (incluso un dios) no puede actuar durante 2 turnos.";
I18N.DICT.es.T.nh[1] = "Teletransporta a uno de tus guardias o soldados a la zona rival.";
I18N.DICT.es.T.ni[1] = "Mata a todos los soldados enemigos pegados a tus unidades.";
I18N.DICT.es.T.nj[1] = "Tu unidad y sus vecinas no pueden morir hasta tu turno.";
I18N.DICT.es.T.nk[1] = "Todas tus Sombras (soldados) avanzan una casilla.";
I18N.DICT.es.T.om[1] = "Hace nacer una Sombra (soldado) junto a una de tus unidades.";
I18N.DICT.es.T.of[1] = "Mata a un enemigo (no un dios) pegado a una de tus unidades.";
I18N.DICT.es.T.oe[1] = "En el próximo turno rival: ni colocar ni activar.";
I18N.DICT.es.T.ou[1] = "Sacrifica una de tus unidades pegadas a él: +60 de maná.";
I18N.DICT.es.T.oa[1] = "1 paso, o un salto de 2 o 3 casillas por encima de todo; captura al llegar.";
I18N.DICT.es.T.ob[1] = "Se teletransporta a una casilla oscura libre a 4 casillas o menos, o se come a un vecino.";
I18N.DICT.es.T.oc[1] = "Vuela en diagonal hasta 4 casillas; captura al llegar.";
I18N.DICT.es.T.ol[1] = "Embiste 2 casillas en línea recta y mata todo a su paso.";
I18N.DICT.es.T.ox[1] = "Vuela 1 o 2 casillas por encima de todo; captura al llegar.";
I18N.DICT.es.T.os[1] = "1 paso recto (incluso hacia atrás); captura en diagonal hacia delante.";
I18N.DICT.es.T.n1[1] = "Se posa a 3 casillas o menos; mata a los soldados enemigos pegados y paraliza a los guardias.";
I18N.DICT.es.T.n2[1] = "1 paso (captura); tras cada captura, da otro paso (3 como máximo).";
I18N.DICT.es.T.n3[1] = "Muerde a un enemigo a 2 casillas sin moverse (no un dios): +20 de maná. O 1 paso.";
I18N.DICT.es.T.n4[1] = "Tela a 4 casillas en línea: mata a un soldado, paraliza a un guardia 2 turnos. O 1 paso.";
I18N.DICT.es.T.n5[1] = "Lanza a un enemigo cercano 2 casillas más lejos: muere si cae mal. O 1 paso.";
I18N.DICT.es.T.n6[1] = "Repta hasta 4 casillas girando como quiera; captura al final.";
I18N.DICT.es.T.n7[1] = "1 paso (captura); pegado a 2 enemigos o más, los mata a todos.";
I18N.DICT.es.T.n8[1] = "1 paso, captura en diagonal; al morir, da 2 Sombras.";
I18N.DICT.es.T.n9[1] = "1 paso (captura), o surge junto a un dios enemigo.";
I18N.DICT.es.T.nl[1] = "1 paso (captura), o lanza un hueso a 2 o 3 casillas; al morir, vuelve como Sombra.";
I18N.DICT.es.T.nm[1] = "1 paso, o salta a su reflejo (misma fila, otro lado) y captura allí.";
I18N.DICT.es.T.nn[1] = "Mata a un enemigo vecino que también esté pegado a otra de tus unidades. O 1 paso.";
I18N.DICT.es.T.no[1] = "Se lanza hasta 4 casillas hacia el rival; captura al final.";
// armée des Ombres : descriptions claires
I18N.DICT.es.T.na[1] = "Un enemigo pegado a una de tus unidades pasa a tu bando (no un dios).";
I18N.DICT.es.T.nb[1] = "Maldice a un enemigo: si no se ha movido al final de su próximo turno, muere.";
I18N.DICT.es.T.nc[1] = "Mueve una de tus unidades (no un dios) a una casilla vacía pegada a otra de tus unidades.";
I18N.DICT.es.T.nd[1] = "Quita 50 de maná al rival y te los da.";
I18N.DICT.es.T.ne[1] = "Los enemigos (no los dioses) que están en tu lado del mapa retroceden una casilla.";
I18N.DICT.es.T.nf[1] = "Añade a tu reserva 3 Sombras (soldados), +1 por cada guardia que hayas perdido.";
I18N.DICT.es.T.ng[1] = "Un enemigo a tu elección (incluso un dios) no puede activarse durante sus 2 próximos turnos.";
I18N.DICT.es.T.nh[1] = "Mueve a uno de tus guardias o soldados a una casilla vacía de la zona rival.";
I18N.DICT.es.T.ni[1] = "Mata a todos los soldados enemigos pegados al menos a una de tus unidades.";
I18N.DICT.es.T.nj[1] = "Elige una de tus unidades: ella y tus unidades pegadas a ella no pueden morir hasta tu próximo turno.";
I18N.DICT.es.T.nk[1] = "Cada una de tus Sombras (soldados) avanza una casilla hacia el rival.";
I18N.DICT.es.T.om[1] = "Coloca una Sombra (soldado) en una casilla vacía pegada a una de tus unidades.";
I18N.DICT.es.T.of[1] = "Mata a un enemigo (no un dios) pegado a una de tus unidades.";
I18N.DICT.es.T.oe[1] = "En su próximo turno, el rival no puede colocar ni activar unidades.";
I18N.DICT.es.T.ou[1] = "Sacrifica una de tus unidades pegadas a él (no un dios): ganas 60 de maná.";
I18N.DICT.es.T.oa[1] = "1 paso recto, o un salto recto de 2 o 3 casillas por encima de todo. Captura al enemigo de la casilla de llegada.";
I18N.DICT.es.T.ob[1] = "Se teletransporta a una casilla oscura vacía a 4 casillas o menos, o captura a un enemigo pegado a ella.";
I18N.DICT.es.T.oc[1] = "Vuela en diagonal hasta 4 casillas, por encima de todo. Captura al enemigo de la casilla de llegada.";
I18N.DICT.es.T.ol[1] = "Avanza 2 casillas en una de las 8 direcciones y mata a todos los enemigos de esas 2 casillas.";
I18N.DICT.es.T.ox[1] = "1 paso a una casilla vacía, o un vuelo de 2 casillas en las 8 direcciones, por encima de todo. Captura al enemigo de la casilla de llegada.";
I18N.DICT.es.T.os[1] = "1 paso recto a una casilla vacía (incluso hacia atrás). Captura en diagonal hacia delante.";
I18N.DICT.es.T.n1[1] = "Se posa en una casilla vacía a 3 casillas o menos. Allí, los soldados enemigos pegados mueren y los guardias pegados quedan paralizados 1 turno.";
I18N.DICT.es.T.n2[1] = "1 paso en las 8 direcciones, capturando al enemigo de su casilla. Tras una captura, puede dar otro paso (3 como máximo).";
I18N.DICT.es.T.n3[1] = "Mata sin moverse a un enemigo a 1 o 2 casillas en línea o en diagonal, sin nada en medio (no un dios): +10 de maná. O 1 paso a una casilla vacía.";
I18N.DICT.es.T.n4[1] = "Lanza su tela al 1.er enemigo en línea recta a 4 casillas o menos: un soldado muere, un guardia o un dios queda paralizado 2 turnos. O 1 paso en diagonal (captura al enemigo).";
I18N.DICT.es.T.n5[1] = "Lanza a un enemigo a 1 o 2 casillas (no un dios) 2 casillas más lejos: muere si sale del mapa, cae en un agujero o sobre una unidad. O 1 paso (captura al enemigo).";
I18N.DICT.es.T.n6[1] = "Avanza hasta 3 pasos rectos, girando como quiera, por casillas vacías. Solo captura a un enemigo a 2 pasos o menos.";
I18N.DICT.es.T.n7[1] = "1 paso en las 8 direcciones (captura al enemigo). Si captura, o si está pegado a 2 enemigos o más, entra en furia: mueren todos los enemigos pegados a él (no los dioses).";
I18N.DICT.es.T.n8[1] = "1 paso recto (captura al enemigo), o captura en diagonal. Cuando muere, aparecen 2 Sombras a su alrededor.";
I18N.DICT.es.T.n9[1] = "1 paso en las 8 direcciones (captura al enemigo de su casilla), o aparece en una casilla vacía pegada a un dios enemigo.";
I18N.DICT.es.T.nl[1] = "1 paso recto (captura al enemigo), o mata sin moverse a un enemigo a 2 o 3 casillas en línea recta (no un dios). Cuando muere, aparece una Sombra a su lado.";
I18N.DICT.es.T.nm[1] = "1 paso en las 8 direcciones (captura al enemigo), o salta a la casilla espejo al otro lado de su fila o columna y captura allí al enemigo (no un dios).";
I18N.DICT.es.T.nn[1] = "1 paso en las 8 direcciones (captura al enemigo). O mata sin moverse a un enemigo pegado a él que también esté pegado a otra de tus unidades (no un dios).";
I18N.DICT.es.T.no[1] = "Avanza en línea recta hacia el rival todo lo que quiera, por casillas vacías, y captura al enemigo de la casilla de llegada. O 1 paso a una casilla vacía.";
I18N.DICT.es.T.n3[1] = "Muerde sin moverse a un enemigo pegado a él (no un dios): muere y ganas 10 de maná. O 1 paso a una casilla vacía.";
I18N.DICT.es.T.n6[1] = "Avanza hasta 3 pasos rectos por casillas vacías, girando como quiera. Solo captura a un enemigo pegado a él (en línea recta).";
I18N.DICT.es.T.n8[1] = "1 paso en las 8 direcciones (captura al enemigo). Cuando muere, aparecen 2 Sombras a su alrededor.";
// équilibrage du 2026-10-24
I18N.DICT.es.T.g3[1] = "Dispara en diagonal: mata al primer enemigo de la diagonal sin moverse. O da 1 paso en cualquier dirección.";
I18N.DICT.es.T.g4[1] = "Avanza 1 casilla en las 8 direcciones empujando toda la fila de delante (una unidad empujada fuera del mapa o a un agujero muere), y luego puede dar un 2.º paso a una casilla vacía o sobre un soldado enemigo para capturarlo.";
I18N.DICT.es.T.g6[1] = "Puede dar primero 1 paso y luego golpea todas las casillas a su alrededor: mueren todos los enemigos pegados.";
I18N.DICT.es.T.c5[1] = "Se posa en cualquier casilla a más de 6 casillas (filas + columnas); puede capturar allí un soldado, o un guardia a más de 8 casillas, nunca un dios.";
I18N.DICT.es.T.c6[1] = "1 paso en cualquier dirección (captura al enemigo). O convierte a uno de tus soldados pegados en 60 de maná (el soldado desaparece) y vuelves a jugar enseguida. O te da 30 de maná.";
I18N.DICT.es.T.lc[1] = "Golpea las 4 casillas delante de él en línea recta (arriba, abajo, izquierda o derecha) sin moverse. Si no hay ningún enemigo en esa dirección, avanza un paso.";
I18N.DICT.es.T.n6[1] = "Avanza hasta 4 pasos rectos por casillas vacías, girando como quiera, y puede terminar sobre un enemigo para capturarlo.";
I18N.DICT.es.T.n8[1] = "1 paso en las 8 direcciones (captura al enemigo). Cuando muere, aparecen 3 Sombras a su alrededor.";
I18N.DICT.es.T.cv[1] = "Salta en L como el caballo de ajedrez, por encima de todo. O da 1 paso en cualquier dirección.";
I18N.DICT.es.T.n6[1] = "Avanza hasta 4 pasos rectos por casillas vacías, girando como quiera. Puede capturar a un enemigo a 2 pasos como mucho.";
I18N.DICT.es.T.g4[1] = "Avanza 1 casilla en las 8 direcciones empujando toda la fila de delante (una unidad empujada fuera del mapa o a un agujero muere), y luego puede dar un 2.º paso recto, a una casilla vacía o sobre un enemigo (no un dios) para capturarlo.";
I18N.DICT.es.T.c2[1] = "Avanza en diagonal tantas casillas como quiera (como el alfil del ajedrez). O da 1 paso recto a una casilla vacía.";
I18N.DICT.es.T.n6[1] = "Avanza hasta 3 pasos rectos por casillas vacías, girando como quiera. Puede capturar a un enemigo a 2 pasos como mucho.";
I18N.DICT.es.T.c3[1] = "Se teletransporta a una casilla pegada a un soldado (cualquiera) o a una de tus unidades.";
// boss rééquilibrés (2026-10-24)
I18N.DICT.es.T.bs[1] = "Jefe, 4 puntos de vida. Al final de cada turno de su bando, aparece junto a tu unidad más valiosa. Es intangible (no se le puede tocar) 1 turno de cada 3; cada 3 turnos se lleva una de tus unidades pegadas a él.";
I18N.DICT.es.T.bg[1] = "Jefa, 2 puntos de vida. Un turno de cada dos, congela tu unidad más valiosa del mapa: no puedes activarla en tu siguiente turno.";
I18N.DICT.es.T.bv[1] = "Jefe, 2 puntos de vida. Un turno de cada dos, marca en rojo la casilla de tu guardia o soldado más valioso; al turno siguiente brota allí la lava: si sigue encima, muere.";
I18N.DICT.es.T.bc[1] = "Jefe, 3 puntos de vida, rodeado de 4 secuaces. Al final de cada turno de su bando, su secuaz más cercano a ti avanza un paso hacia tus unidades (y captura si llega a una).";
I18N.DICT.es.T.bq[1] = "Jefa, 4 puntos de vida. Al final de cada turno de su bando, una abeja sale de la colmena junto a ella (4 como máximo). Las abejas vuelan 2 casillas por encima de todo.";
I18N.DICT.es.T.sa[1] = "Jefe de la Luz, 5 puntos de vida. En cada turno, su luz ciega a todas tus unidades de su fila y su columna: no puedes activarlas en tu siguiente turno.";
I18N.DICT.es.T.sp[1] = "Jefe de la Luz, 5 puntos de vida. Mientras 2 de sus unidades estén pegadas a él, lo protegen: tus golpes no le hacen nada. ¡Mata primero a sus guardias! Avanza hacia ti un turno de cada dos (a veces dejando atrás a sus guardias) y golpea a una unidad pegada a él cada 3 turnos.";
I18N.DICT.es.T.bp[1] = "Jefe, 2 puntos de vida, pero renace una vez de sus cenizas con 2 puntos de vida, quemando tus unidades pegadas a él. Un turno de cada dos, sus llamas matan a 2 de tus unidades a 2 casillas de él.";
I18N.DICT.es.T.bt[1] = "Jefe, 5 puntos de vida. Al final de cada turno de su bando, avanza una casilla hacia tu unidad más cercana; un turno de cada dos, aplasta a una de tus unidades pegadas a él.";
I18N.DICT.es.T.n6[1] = "Avanza hasta 3 pasos rectos por casillas vacías, girando como quiera. Solo captura a un enemigo pegado a él (en línea recta).";
// descriptions plus claires (2026-10-30)
I18N.DICT.es.T.g4[1] = "Da 1 paso en cualquier dirección. Si hay unidades delante, las empuja a todas una casilla (una unidad empujada fuera del mapa o a un agujero muere). Después puede dar un 2.º paso recto, a una casilla vacía o sobre un enemigo (no un dios) para matarlo.";
I18N.DICT.es.T.g5[1] = "Da hasta 3 pasos seguidos. En cada paso: recto (arriba, abajo, izquierda, derecha) a una casilla vacía, o en diagonal sobre un enemigo para matarlo.";
I18N.DICT.es.T.g6[1] = "Puede dar primero 1 paso y luego gira sobre sí mismo: mueren todos los enemigos de las 8 casillas a su alrededor.";
I18N.DICT.es.T.c3[1] = "Desaparece y reaparece en una casilla pegada a un soldado (de cualquier bando) o a una de tus unidades. Si hay un enemigo en esa casilla, lo mata.";
I18N.DICT.es.T.c5[1] = "Salta lejos: se posa en una casilla a más de 6 casillas (sumando filas y columnas). Si hay un soldado enemigo en esa casilla, lo mata; un guardia enemigo solo si está a más de 8 casillas; nunca un dios.";
I18N.DICT.es.T.c8[1] = "Da 1 paso en cualquier dirección (mata al enemigo si lo hay). O salta por encima de toda una fila de unidades pegadas y cae en la casilla vacía justo después.";
I18N.DICT.es.T.n1[1] = "Se posa en una casilla vacía a 3 casillas o menos. Al llegar, mueren los soldados enemigos pegados a él, y los guardias enemigos pegados no pueden activarse el turno siguiente.";
I18N.DICT.es.T.n4[1] = "Lanza su tela en línea recta (arriba, abajo, izquierda, derecha) al primer enemigo a 4 casillas o menos: un soldado muere; un guardia o un dios queda atrapado y no puede activarse durante 2 turnos. O da 1 paso en diagonal (mata al enemigo si lo hay).";
I18N.DICT.es.T.n5[1] = "Agarra a un enemigo (no un dios) a 1 o 2 casillas en línea recta o diagonal y lo lanza 2 casillas más lejos en la misma dirección: muere si sale del mapa, cae en un agujero o cae sobre otra unidad. O da 1 paso (mata al enemigo si lo hay).";
I18N.DICT.es.T.nl[1] = "Da 1 paso recto (arriba, abajo, izquierda, derecha) y mata al enemigo si lo hay. O, sin moverse, mata a un enemigo (no un dios) a 2 o 3 casillas en línea recta. Cuando muere, aparece una Sombra (soldado) a su lado.";
I18N.DICT.es.T.nm[1] = "Da 1 paso en cualquier dirección (mata al enemigo si lo hay). O salta a la casilla simétrica al otro lado del mapa, en su fila o su columna (allí mata al enemigo, no a un dios).";
I18N.DICT.es.T.ob[1] = "Se teletransporta a una casilla oscura vacía a 4 casillas o menos. O, sin moverse, mata a un enemigo pegado a ella.";
I18N.DICT.es.THEME.printemps = ["Bosque de primavera"];
I18N.DICT.es.THEME.jungle = ["Jungla"];
I18N.DICT.es.THEME.volcan = ["Volcán"];
I18N.DICT.es.THEME.canyon = ["Cañón"];
I18N.DICT.es.T.bb[1] = "Jefe, 5 puntos de vida. Un turno de cada dos, fija una línea recta (marcada en rojo); al turno siguiente, su mirada convierte en piedra a la primera de tus unidades en esa línea.";
I18N.DICT.es.T.sa[1] = "Jefe de la Luz, 6 puntos de vida. En cada turno, su luz ciega a todas tus unidades de su fila y su columna: no puedes activarlas en tu siguiente turno.";
// nouveaux déplacements (2026-10-30)
I18N.DICT.es.T.cv[1] = "Salta en L como el caballo del ajedrez, o 2 casillas en línea recta (arriba, abajo, izquierda, derecha), por encima de todo. Mata al enemigo donde cae (no a un dios).";
I18N.DICT.es.T.g3[1] = "Dispara en diagonal: mata al 1.er enemigo de la diagonal sin moverse, aunque esté pegado a él. O se desliza 1 o 2 casillas vacías en línea recta (arriba, abajo, izquierda, derecha).";
I18N.DICT.es.T.c6[1] = "Salta 2 casillas en cualquier dirección, por encima de todo, o da 1 paso en diagonal (mata al enemigo donde cae, no a un dios). O convierte a uno de tus soldados pegados a él en 70 de maná (el soldado desaparece) y vuelves a jugar enseguida. O te da 40 de maná.";
I18N.DICT.es.T.n3[1] = "Muerde sin moverse a un enemigo pegado a él (no a un dios): muere y ganas 10 de maná. O se desliza en diagonal 1 o 2 casillas vacías.";
I18N.DICT.es.T.n8[1] = "Avanza en línea recta hacia el rival 1 o 2 casillas vacías, o da 1 paso de lado. Mata en las 3 casillas justo delante de ella. Cuando muere, aparecen 3 Sombras a su alrededor.";
I18N.DICT.es.T.n9[1] = "Salta 2 o 3 casillas en línea recta o en diagonal, por encima de todo, y mata allí al enemigo (no a un dios). O aparece en una casilla vacía pegada a un dios enemigo.";
I18N.DICT.es.T.no[1] = "Se desliza tan lejos como quiera por casillas vacías, en línea recta hacia el rival o de lado (izquierda, derecha), y captura al enemigo en su casilla de llegada.";
// tenaille et Démon (2026-10-31)
I18N.DICT.es.T.na[1] = "Un enemigo (no un dios) atrapado en tenaza, pegado a al menos 2 de tus unidades, se pasa a tu bando.";
I18N.DICT.es.T.of[1] = "Mata a un enemigo (no un dios) atrapado en tenaza: pegado a al menos 2 de tus unidades.";
I18N.DICT.es.T.n9[1] = "Salta 2 casillas a una casilla vacía, o 3 casillas para matar al enemigo que esté allí (no a un dios), en línea recta o en diagonal, por encima de todo. O aparece en una casilla vacía pegada a un dios enemigo.";
